/* ATB Atlas V18 — atlas clínico editorial. UI original; never interpret missing pilot records as resistance. */
'use strict';
let WHO={meta:{},conditions:[]};
fetch('data/who-conditions.json',{cache:'no-cache'}).then(r=>r.json()).then(d=>{WHO=d;if(D)render()}).catch(e=>console.warn('WHO library could not load',e));
Object.assign(state,{onlyKnown:false,treeOpen:storage.get('atb18_tree',{}),group:'all',category:'all',section:'',clinicalId:'who-12',labClinical:'who-12',labSystem:'all',browserQuery:'',pickerOpen:'',pickerSearch:'',mapFilter:'all',mapSearch:'',mapCollapsed:false,comparSearch:'',learnIndex:storage.get('atb18_quizidx',0),learnChoice:null,quizAnswers:storage.get('atb18_quizanswers',{}),topic:'all',showDrugPicker:false});
const SYSTEMS={Respiratorio:['#3483DF','pulmones'],Urinario:['#159C8A','riñón'],Gastrointestinal:['#4c91c3','intestino'],'Piel y tejidos blandos':['#D84E77','piel'],Otorrinolaringología:['#A66BDD','ORL'],Odontología:['#5496c5','dental'],Oftalmología:['#4D91BC','ojo'],ITS:['#B15ABC','ITS'],Sistémico:['#A54F4C','sepsis'],Pediatría:['#5B91A9','pediatría'],'Sistema nervioso':['#6959CA','SNC'],Hepatobiliar:['#397aa8','hígado'],Osteoarticular:['#8F75C9','hueso'],Hematología:['#D15963','hematología'],Quirúrgico:['#597D77','cirugía'],Abdomen:['#5a9ac7','abdomen'],Piel:['#D84E77','piel'],SNC:['#6959CA','SNC']};
const sysColor=name=>(SYSTEMS[name]||['#73839F'])[0];
const whoc=id=>WHO.conditions.find(x=>x.id===id);
const allDiseases=()=>WHO.conditions.length?WHO.conditions:[];
const sysStyle=name=>`style="--sys:${sysColor(name)}"`;
const excerpt=(s,n=210)=>!s?'':String(s).length>n?String(s).slice(0,n-1)+'…':String(s);
const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
const findRx=s=>D.antibiotics.find(a=>norm(a.name)===norm(s))||D.antibiotics.find(a=>norm(a.name).startsWith(norm(s)) || norm(s).startsWith(norm(a.name)))||null;
const fromManualForDrug=a=>allDiseases().flatMap(c=>[...c.first.map(rx=>({...rx,choice:'Primera elección',condition:c})),...c.alternatives.map(rx=>({...rx,choice:'Alternativa',condition:c}))]).filter(rx=>norm(rx.drug).includes(norm(a.name))||norm(a.name).includes(norm(rx.drug)) || (a.id==='amoxi-clav'&&norm(rx.drug).includes('amoxicilinaclavulanato')) || (a.id==='trimetoprim-sulfametoxazol' && norm(rx.drug).includes('trimetoprim')));
const relValue=(a,p)=>rstatus(relation(a,p));
const cntR=id=>relsP(id).length;
const listGroupItems=(micro,key)=>micro?D.pathogens.filter(p=>p.groupId===key):D.antibiotics.filter(a=>a.family===key);
const hierarchy=(micro)=>micro?D.groups.map(g=>({id:g.id,title:g.name,caption:g.domain,items:listGroupItems(true,g.id),color:grpcolor(g.id)})): [...new Set(D.antibiotics.map(a=>a.family))].sort((a,b)=>a.localeCompare(b,'es')).map(f=>({id:f,title:f,caption:[...new Set(D.antibiotics.filter(a=>a.family===f).map(a=>a.subgroup))].filter(Boolean).join(' · '),items:listGroupItems(false,f),color:'#986AC2'}));
const navTitle=(route)=>NAV.find(x=>x[0]===route)?.[2]||'ATB Atlas';
function header(){return `<header class="a18-mast"><button class="a18-brand" data-act="nav:mapa"><span class="a18-mark">A<span>✳</span></span><span><b>ATB <i>ATLAS</i></b><small>THE CLINICAL FIELD GUIDE <strong>18.0</strong></small></span></button><nav id="site-nav" class="a18-nav">${NAV.map(([id,ico,label],i)=>`<button class="${state.route===id?'on':''}" data-act="nav:${id}">${ic(ico,16)}<span>${H(label)}</span></button>`).join('')}</nav><div class="a18-toptools"><button class="a18-iconbtn" data-act="search-global" title="Buscar en todo el atlas">${ic('search',18)}</button><button class="a18-iconbtn" data-act="palette" title="Personalizar colores">${ic('palette',18)}</button><button class="a18-iconbtn a18-menu" data-act="menu" title="Menú">${ic('menu',18)}</button></div></header>`}
function footer(){return `<footer class="a18-footer"><strong>ATB / ATLAS · VOL. 18</strong><span>Guía educativa interactiva. Las dosis documentadas corresponden al escenario específico de la fuente y no sustituyen ajuste, alergias, embarazo, función renal, susceptibilidad ni guías vigentes.</span><a href="https://github.com/ProQuincy2471/atb-atlas" target="_blank" rel="noreferrer">Código en GitHub ↗</a></footer>`}
function pageHead(idx,over,title,desc,acts=''){return `<div class="a18-head"><span class="a18-serial">${H(idx)} &nbsp; / &nbsp; ${H(over)}</span><div class="a18-headmain"><div><h1>${title}</h1><p>${H(desc)}</p></div>${acts?`<div>${acts}</div>`:''}</div></div>`}
const eyebrow=(s)=>`<span class="a18-eyebrow">${H(s)}</span>`;
const warning=(text)=>`<p class="a18-warning">${ic('alert',16)} ${H(text)}</p>`;
function navAnchors(ids){return `<nav class="a18-localnav" aria-label="Secciones de esta ficha">${ids.map(([id,name,n])=>`<a href="#${id}" data-scroll="${id}"><span>${n}</span>${H(name)}</a>`).join('')}</nav>`}
function sectionBlock(id,n,label,title,body,desc=''){return `<section class="a18-section" id="${id}"><div class="a18-sectiontitle"><span class="a18-chapter">${n}</span><div><span class="a18-eyebrow">${H(label)}</span><h2>${H(title)}</h2>${desc?`<p>${H(desc)}</p>`:''}</div></div><div class="a18-sectionbody">${body}</div></section>`}
const tags=xs=>(xs||[]).filter(Boolean).map(x=>`<span class="a18-tag">${H(x)}</span>`).join('');
const items=xs=>(xs||[]).filter(Boolean).length?`<ul class="a18-proselist">${xs.map(x=>`<li>${H(x)}</li>`).join('')}</ul>`:`<p class="a18-empty">Información individual pendiente de revisión con fuentes específicas.</p>`;
const metric=(label,value,sub='')=>`<div class="a18-metric"><small>${H(label)}</small><b>${H(value)}</b>${sub?`<span>${H(sub)}</span>`:''}</div>`;
function renderPicker(id,selected,options,opts={}){const choice=options.find(x=>String(x.id)===String(selected));const open=state.pickerOpen===id;return `<div class="a18-picker ${open?'is-open':''}" data-picker="${H(id)}"><button class="a18-pickerbtn" aria-haspopup="listbox" aria-expanded="${open}" data-act="picker-toggle:${H(id)}"><span>${opts.kicker?`<small>${H(opts.kicker)}</small>`:''}<strong>${H(choice?.label||opts.placeholder||'Seleccionar…')}</strong></span>${ic('more',17)}</button>${open?`<div class="a18-poplist" role="listbox"><div class="a18-popsearch">${ic('search',15)}<input data-picker-search="${H(id)}" placeholder="Buscar aquí…" autocomplete="off"></div><div class="a18-popopts">${options.map(x=>`<button role="option" class="a18-option" data-act="picker-select:${H(id)}:${H(x.id)}" data-text="${H((x.label+' '+(x.meta||'')).toLowerCase())}" aria-selected="${x.id===selected}">${x.color?`<i style="background:${H(x.color)}"></i>`:''}<span><b>${H(x.label)}</b>${x.meta?`<small>${H(x.meta)}</small>`:''}</span>${x.id===selected?ic('star',15):''}</button>`).join('')}</div></div>`:''}</div>`}
function browser(micro){const tree=hierarchy(micro),chosen=micro?state.micro:state.drug,query=(state.browserQuery||'').toLowerCase();return `<aside class="a18-browser"><div class="a18-browserhead"><span class="a18-eyebrow">${micro?'MICRO LIBRARY':'ANTIBIOTIC INDEX'}</span><h2>${micro?'Biblioteca de especies':'Familias farmacológicas'}</h2><div class="a18-search">${ic('search',17)}<input id="library-search" placeholder="Buscar ${micro?'microorganismo':'antibiótico'}…" value="${H(state.browserQuery)}"></div><span class="a18-browserstats">${micro?D.pathogens.length:D.antibiotics.length} fichas · ${tree.length} grupos <button data-act="clear-library">Limpiar</button></span>${window.INF_FACETS?window.INF_FACETS(micro):''}</div><div class="a18-tree">${tree.map((g,i)=>{const fxOn=window.INF_FXON?window.INF_FXON(micro):false;const visible=g.items.filter(x=>`${x.name} ${x.family||''} ${x.subgroup||''}`.toLowerCase().includes(query)&&(!window.INF_FX||window.INF_FX(micro,x)));if((query||fxOn)&&!visible.length)return '';const expanded=(query||fxOn)?true:state.treeOpen[g.id]===true || (state.treeOpen[g.id]!==false && g.items.some(x=>x.id===chosen));return `<div class="a18-branch" style="--node:${g.color}"><button data-act="tree:${H(g.id)}" class="a18-branchhead"><span class="a18-branchicon">${ic(micro?'micro':'drugs',18)}</span><span class="a18-branchname"><b>${H(g.title)}</b><small>${H(g.caption||'')}</small></span><em>${g.items.length}</em>${ic(expanded?'chevron-up':'chevron',15)}</button>${expanded?`<div class="a18-leaves">${visible.map((x,j)=>`<button class="${x.id===chosen?'selected':''}" data-act="${micro?'micro-pick':'drug-pick'}:${H(x.id)}">${window.INF_LEAF?window.INF_LEAF(micro,x):'<span class="a18-leafdot"></span>'}<span>${H(x.name)}</span>${micro&&cntR(x.id)?`<i>${cntR(x.id)}</i>`:''}</button>`).join('')}</div>`:''}</div>`}).join('')}</div></aside>`}
const WHO_LINK='https://www.who.int/publications/i/item/9789240062382';
function whoRefs(){return `<a class="a18-source" href="${WHO_LINK}" target="_blank" rel="noopener noreferrer">WHO AWaRe antibiotic book, 2022 ↗</a>`}
const MICRO_EDU={
's-aureus-mssa':{definition:'Coco grampositivo, catalasa y coagulasa positivo; coloniza piel y fosas nasales. MSSA expresa susceptibilidad a meticilina; no significa infección poco grave.',risk:['Heridas, accesos vasculares, hemodiálisis y dispositivos','Colonización nasal o cutánea','Diabetes e infecciones purulentas previas'],pathophys:'Adhesinas, citotoxinas y factores de evasión favorecen abscesos, invasión vascular y focos metastásicos. La bacteriemia obliga a valorar endocarditis y diseminación.',distinct:'Para MSSA, los betalactámicos antiestafilocócicos como cefazolina u oxacilina suelen preferirse frente a vancomicina cuando no hay contraindicación.'},
's-aureus-mrsa':{definition:'Fenotipo resistente a meticilina de S. aureus, ligado habitualmente a PBP2a (mecA/mecC). La tinción y morfología no distinguen MRSA de MSSA.',risk:['Antecedente de colonización/infección MRSA','Hospitalización o dispositivos','Infección purulenta recurrente y contactos'],pathophys:'Conserva la capacidad de formar abscesos e invadir tejidos; el fenotipo resistente restringe la utilidad de betalactámicos convencionales.',distinct:'La localización importa: daptomicina no sirve para neumonía alveolar; vancomicina o linezolid entran en escenarios diferentes.'},
's-pneumoniae':{definition:'Diplococo grampositivo encapsulado, alfa-hemolítico. Patógeno respiratorio y meníngeo cuya cápsula dificulta la fagocitosis.',risk:['Edad extrema y enfermedad pulmonar crónica','Asplenia o déficit humoral','Infección viral previa'],pathophys:'Coloniza nasofaringe; la invasión a oído medio, senos, alvéolos o sangre produce enfermedad localizada e invasiva.',distinct:'NAC no es sinónimo de requerir anti-Pseudomonas; el contexto de gravedad y susceptibilidad a penicilina determinan el régimen.'},
's-pyogenes':{definition:'Estreptococo betahemolítico grupo A: coco grampositivo en cadenas, conocido por faringitis, celulitis e infecciones invasivas.',risk:['Contacto cercano / escuelas','Heridas y ruptura de barrera cutánea','Infección viral antecedente'],pathophys:'Proteína M, estreptolisinas y exotoxinas pirogénicas favorecen invasión, inflamación y, en infecciones necrosantes, choque tóxico.',distinct:'Penicilina es una diana clásica; en infección invasiva con toxinas, el papel adicional de clindamicina se justifica por inhibición de síntesis proteica.'},
'e-faecalis':{definition:'Enterococo grampositivo intestinal con resistencia intrínseca a cefalosporinas y perfiles de susceptibilidad variables a ampicilina/vancomicina.',risk:['Hospitalización y antibióticos de amplio espectro','Manipulación urinaria','Endocarditis y foco abdominal'],pathophys:'Oportunista de flora gastrointestinal; puede colonizar orina y catéteres. Requiere establecer significación clínica de aislamiento.',distinct:'No trates Enterococcus como estreptococo habitual: ceftriaxona por sí sola no lo cubre.'},
'e-coli':{definition:'Bacilo gramnegativo fermentador de lactosa, colonizador intestinal y causa frecuente de infección urinaria y bacteriemia.',risk:['Sexo femenino y alteraciones urológicas','Obstrucción o catéter','Hospitalización y antibióticos previos'],pathophys:'Cepas uropatógenas expresan adhesinas y otros factores de virulencia que facilitan ascenso al urotelio y parénquima renal.',distinct:'E. coli sin fenotipo definido no significa necesariamente susceptible: el antibiograma y los cultivos previos modifican opciones.'},
'e-coli-blee':{definition:'E. coli con betalactamasa de espectro extendido (BLEE), que altera utilidad de múltiples cefalosporinas.',risk:['Aislamientos BLEE previos','Exposición reciente a cefalosporinas o fluoroquinolonas','Infección asociada a cuidados sanitarios'],pathophys:'Enzimas capaces de hidrolizar cefalosporinas de espectro extendido; el resultado fenotípico y la susceptibilidad a agentes alternativos guían el tratamiento.',distinct:'IDSA desaconseja cefepima en pielonefritis o ITU complicada por BLEE; TMP-SMX o fluoroquinolonas pueden servir si son susceptibles, y carbapenémicos según gravedad/contexto.'},
'p-aeruginosa':{definition:'Bacilo gramnegativo no fermentador, oxidasa positivo, ambiental. Tiene permeabilidad reducida, bombas de eflujo y otros mecanismos de resistencia intrínseca.',risk:['Estancia hospitalaria y ventilación mecánica','Bronquiectasias y fibrosis quística','Quemaduras, instrumentalización y antibióticos previos'],pathophys:'Biopelículas y persistencia en superficies húmedas facilitan colonización e infección en huéspedes vulnerables.',distinct:'Ceftriaxona y ertapenem no son antipseudomónicos; usar especie y susceptibilidad, no solamente la etiqueta de «amplio espectro».'},
'b-fragilis':{definition:'Bacilo gramnegativo anaerobio intestinal que participa en infecciones mixtas y abscesos intraabdominales.',risk:['Perforación o cirugía gastrointestinal','Abscesos profundos','Control de foco insuficiente'],pathophys:'La contaminación de espacios estériles junto con enterobacterales produce infección polimicrobiana; cápsula favorece abscesos.',distinct:'Cefepima aislada no cubre B. fragilis; combinarla con metronidazol puede cubrir anaerobios si el resto del esquema lo justifica.'},
'clostridioides-difficile':{definition:'Bacilo grampositivo anaerobio formador de esporas; causa colitis asociada a alteraciones de la microbiota intestinal.',risk:['Antibióticos recientes y hospitalización','Edad avanzada','Recurrencia previa'],pathophys:'Disbiosis permite sobrecrecimiento y liberación de toxinas A y B, con daño epitelial e inflamación colónica.',distinct:'Vancomicina oral y vancomicina IV no son equivalentes para enfermedad luminal intestinal.'},
'nocardia-spp':{definition:'Bacilos filamentosos ramificados, aerobios y parcialmente ácido-alcohol resistentes; diferenciarlos de Actinomyces.',risk:['Trasplante y glucocorticoides','Inmunosupresión celular','Enfermedad pulmonar crónica'],pathophys:'Inoculación inhalatoria o cutánea; puede diseminarse al SNC y provocar abscesos en inmunocomprometidos.',distinct:'TMP-SMX tiene papel central en muchos esquemas, pero especie, resistencia y enfermedad grave requieren tratamiento guiado por susceptibilidad.'},
'legionella':{definition:'Bacilo gramnegativo intracelular facultativo que no se visualiza bien con Gram rutinario; adquirido habitualmente por aerosoles acuáticos.',risk:['Viajes, hoteles y sistemas de agua','Edad mayor, tabaquismo','Inmunosupresión'],pathophys:'Se multiplica en macrófagos alveolares; agentes con actividad intracelular son relevantes.',distinct:'Ceftriaxona sola no cubre adecuadamente Legionella; pensar en macrólidos o fluoroquinolonas según escenario.'},
'mycoplasma':{definition:'Bacteria sin pared celular clásica, de tamaño pequeño, asociada a neumonía atípica en jóvenes.',risk:['Ambientes colectivos','Escolares/adultos jóvenes','Contacto estrecho'],pathophys:'Se adhiere al epitelio respiratorio; la ausencia de pared explica la falta de actividad de betalactámicos.',distinct:'Doxiciclina y macrólidos actúan sobre proteínas; la ausencia de pared explica por qué amoxicilina no es útil.'},
'k-pneumoniae':{definition:'Bacilo gramnegativo encapsulado fermentador de lactosa, colonizador intestinal, con potencial de neumonía, ITU y bacteriemia.',risk:['Hospitalización prolongada','Dispositivos y antibioterapia reciente','Diabetes e inmunosupresión'],pathophys:'Cápsula prominente ayuda a evitar la fagocitosis; cepas con carbapenemasas requieren estrategias especializadas.',distinct:'Separar Klebsiella común de variantes CRE; no asumir susceptibilidad uniforme a cefalosporinas.'},
'acinetobacter-baumannii-crab':{definition:'A. baumannii resistente a carbapenémicos (CRAB), patógeno hospitalario complejo con múltiples mecanismos de resistencia.',risk:['UCI y ventilación mecánica','Heridas y dispositivos invasivos','Exposición antibiótica prolongada'],pathophys:'Persistencia ambiental y colonización de superficies; distinguir cultivo colonizante de infección verdadera es decisivo.',distinct:'CRAB necesita enfoque específico; no extrapolar las reglas de Pseudomonas a Acinetobacter.'},
'h-influenzae':{definition:'Cocobacilo gramnegativo respiratorio, capsulado o no tipificable, implicado en otitis, sinusitis y neumonía.',risk:['EPOC y alteraciones respiratorias','Extremos de edad','Hacinamiento'],pathophys:'Coloniza vías aéreas; cepas con beta-lactamasa pueden limitar utilidad de aminopenicilinas aisladas.',distinct:'El fenotipo productor de beta-lactamasa importa para elegir amoxicilina frente a amoxicilina/clavulanato.'},
'neisseria-gonorrhoeae':{definition:'Diplococo gramnegativo que infecta mucosas urogenitales, rectales o faríngeas; puede causar enfermedad diseminada.',risk:['Exposición sexual sin protección','Infección previa y parejas múltiples','Coinfección por otras ITS'],pathophys:'Pili y variación antigénica favorecen adhesión y reinfección; la vigilancia de resistencia guía elección.',distinct:'En gonorrea, esquema y dosis requieren fuente CDC vigente, región y localización.'}
};
function microPageSections(p){const e=MICRO_EDU[p.id]||{},rels=[...relsP(p.id)].sort((a,b)=>['active','conditional','none'].indexOf(rstatus(a))-['active','conditional','none'].indexOf(rstatus(b)));const linked=D.syndromes.filter(s=>(s.pathogenIds||[]).includes(p.id));const g=G(p.groupId);const anchors=[['micro-identidad','Identidad','01'],['micro-escenarios','Enfermedades','02'],['micro-patogenia','Factores y fisiopatología','03'],['micro-espectro','Relación con ATB','04'],['micro-estudio','Preguntas','05'],['micro-referencias','Fuentes','06']];return `<div class="a18-profilehero" style="--hero:${grpcolor(p.groupId)}"><div>${eyebrow('MICROBIOLOGÍA · '+g.name)}<h1>${H(p.name)}</h1><p class="a18-lead">${H(e.definition||p.identity)}</p><div class="a18-tagrow">${tags([p.domain,p.morphology,...(p.aliases||[]).slice(0,3)])}</div></div><div class="a18-heroside"><div class="a18-spectrumglyph" style="--hero:${grpcolor(p.groupId)}">${ic('micro',38)}</div><span class="a18-eyebrow">PERFIL TAXONÓMICO</span><strong>${H(g.name)}</strong><small>${H(p.morphology)}</small>${metric('Relaciones registradas',String(rels.length),'Registros preliminares del catálogo')}</div></div>${navAnchors(anchors)}
${sectionBlock('micro-identidad','01','Qué es / Identificación','Identidad microbiológica',`<div class="a18-duocol"><div class="a18-reading"><p>${H(e.definition||p.identity)}</p><div class="a18-factgrid">${metric('Tinción / clase',p.domain||g.domain||'Por caracterizar')}${metric('Morfología',p.morphology||g.morphology||'Por caracterizar')}${metric('Familia / territorio',g.name)}</div></div><div class="a18-keypanel"><b>La idea esencial</b><p>${H(e.distinct||p.pearl||'La identificación debe complementarse con el foco clínico y la sensibilidad.')}</p></div></div>`) }
${sectionBlock('micro-escenarios','02','Dónde lo encuentras','Enfermedades y presentaciones clásicas',`<p class="a18-readingtext">${H(p.clinical||'El contexto clínico y epidemiológico orienta la sospecha.')}</p><div class="a18-tilegrid">${linked.map(s=>`<button class="a18-diseasejump" data-act="open-syndrome:${s.id}"><span class="a18-diseaseicon" style="--sys:${sysColor(s.site)}">${ic('clinic',18)}</span><b>${H(s.name)}</b><small>${H(s.site)}</small>${ic('next',16)}</button>`).join('')||`<div class="a18-quietnote">No hay enfermedades ligadas individualmente en el catálogo anterior. Consulta la presentación clínica textual y la biblioteca de síndromes.</div>`}</div>`,'El aislamiento debe interpretarse según huésped, foco, colonización y calidad de la muestra.')}
${sectionBlock('micro-patogenia','03','Por qué infecta','Factores de riesgo y fisiopatología',`<div class="a18-duocol"><article class="a18-infobox"><h3>¿En quién pensaría?</h3>${items(e.risk||[])}</article><article class="a18-infobox"><h3>¿Qué mecanismo explica la enfermedad?</h3><p>${H(e.pathophys||'Fisiopatología específica en revisión; no extrapolar factores de virulencia de otras especies.')}</p><p class="a18-smallmuted">${H(p.pearl||'')}</p></article></div>`)}
${sectionBlock('micro-espectro','04','Cobertura real vs ausente','Qué antibióticos tienen datos registrados',`<div class="a18-coveragecards">${['active','conditional','none'].map(st=>`<div class="a18-covergroup s-${st}"><header>${statusBadge(st)}<b>${rels.filter(r=>rstatus(r)===st).length} cruces</b></header>${rels.filter(r=>rstatus(r)===st).map(r=>`<button data-act="open-drug:${r.antibiotic}"><b>${H(A(r.antibiotic)?.name||r.antibiotic)}</b><small>${H(excerpt(r.note,110))}</small>${ic('next',14)}</button>`).join('')||'<p>No hay cruces registrados en este estado.</p>'}</div>`).join('')}</div>${warning('La ausencia de un antibiótico en esta sección significa que NO fue evaluado en el corpus; no es sinónimo de resistencia. Los registros presentes también son preliminares.')}`)}
${sectionBlock('micro-estudio','05','Integración académica','Cómo estudiarlo y reconocerlo',`<div class="a18-teaching"><div><h3>Pregunta de reconocimiento</h3><p>¿Qué rasgo de morfología, huésped y síndrome hace pensar en ${H(p.name)} antes que en otro microorganismo?</p><small>Usa Gram + disposición + puerta de entrada + manifestación clásica.</small></div><div><h3>Pregunta de selección</h3><p>Si el cultivo confirma ${H(p.name)}, ¿qué falta conocer antes de elegir un tratamiento?</p><small>${H(e.distinct||'Fenotipo, susceptibilidad, foco y farmacocinética en el tejido afectado.')}</small></div></div>`)}
${sectionBlock('micro-referencias','06','Evidencia y lectura','Referencias bibliográficas',`<div class="a18-reflist">${linkRefs(p.referenceKeys||[])}<a class="a18-source" href="https://www.idsociety.org/practice-guideline/amr-guidance/" target="_blank" rel="noreferrer">IDSA · resistencia gramnegativa (cuando aplique) ↗</a></div><p class="a18-smallmuted">Las aportaciones farmacológicas originales están redactadas como material didáctico; no son una reproducción textual de los libros adjuntos.</p>`)}`}
function libraryPage(micro){const p=P(state.micro)||D.pathogens[0],a=A(state.drug)||D.antibiotics[0];return `${pageHead(micro?'02':'03',micro?'ATLAS DE ESPECIES':'FARMACOLOGÍA CLÍNICA',micro?'Reconocer <em>al microorganismo.</em>':'Comprender <em>el antibiótico.</em>',micro?'Identidad → enfermedades → fisiopatología → cobertura. Todo en una página continua, con una biblioteca jerárquica compacta.':'Mecanismo → espectro → indicaciones → posología verificada → límites → práctica. Sin pestañas que escondan información.') }<div class="a18-library">${browser(micro)}<article class="a18-article">${micro?microPageSections(p):drugPageSections(a)}</article></div>`}
const DRUG_EDU={
'ceftriaxona':{adverse:['Colestasis / seudolitiasis biliar','Considerar compatibilidad de calcio IV, especialmente en neonatos'],pk:'Betalactámico tiempo-dependiente (%fT>MIC). Buena penetración al LCR con meninges inflamadas en dosis apropiadas.',classic:['Neumonía adquirida en comunidad','Meningitis bacteriana (en combinación según contexto)','ITU alta y bacteriemia por susceptibles'],missing:['No es antipseudomónica','Sin actividad útil contra Enterococcus'],mechanism:'Se une a PBPs, inhibe transpeptidación de peptidoglucano; bactericida.'},
'cefepima':{adverse:['Neurotoxicidad, especialmente si hay insuficiencia renal y dosis no ajustada'],pk:'Betalactámico tiempo-dependiente; ajustar a función renal.',classic:['Neumonía hospitalaria con riesgo de bacilos gramnegativos','Pseudomonas susceptible','Neutropenia febril seleccionada'],missing:['No cubre anaerobios intraabdominales por sí sola','No recomendada para infección invasiva por BLEE pese a aparente susceptibilidad'],mechanism:'Cefalosporina de 4ª generación, unión a PBPs e inhibición de pared.'},
'vancomicina-iv':{adverse:['Nefrotoxicidad, especialmente con exposición elevada','Reacciones relacionadas con infusión'],pk:'Exposición AUC/MIC guía dosificación en infecciones MRSA graves; monitorización según protocolo.',classic:['Infección invasiva por MRSA','Bacteriemia y endocarditis por grampositivos susceptibles','Cobertura empírica de MRSA cuando realmente está indicada'],missing:['No cubre gramnegativos','IV no es útil para colitis luminal por C. difficile'],mechanism:'Glucopéptido, unión al extremo D-Ala-D-Ala del precursor de pared.'},
'meropenem':{adverse:['Convulsiones poco frecuentes (riesgo mayor según condiciones predisponentes)','Efectos gastrointestinales y selección de flora resistente'],pk:'Carbapenémico tiempo-dependiente; suele requerir ajuste renal.',classic:['Infección grave por Enterobacterales BLEE','Infección intraabdominal compleja','Gramnegativos hospitalarios y Pseudomonas susceptible'],missing:['No cubre MRSA','No extrapolar utilidad a CRE sin susceptibilidad'],mechanism:'Carbapenémico inhibidor de PBPs con estabilidad frente a muchas beta-lactamasas.'},
'amoxicilina':{adverse:['Exantema o reacción de hipersensibilidad','Diarrea / intolerancia gastrointestinal'],pk:'Betalactámico tiempo-dependiente, biodisponibilidad oral útil.',classic:['Faringitis estreptocócica','Neumonía comunitaria leve','Otitis y sinusitis seleccionadas'],missing:['No cubre Pseudomonas','S. aureus productor de penicilinasa suele ser resistente'],mechanism:'Aminopenicilina, inhibe PBPs y formación de pared celular.'},
'amoxi-clav':{adverse:['Diarrea','Hepatotoxicidad idiosincrásica, a veces colestásica'],pk:'Betalactámico tiempo-dependiente. Clavulanato inhibe ciertas beta-lactamasas.',classic:['Mordeduras','Sinusitis / otitis seleccionadas','Infecciones de flora oral y tejidos blandos mixtas'],missing:['No cubre Pseudomonas','No garantiza actividad frente a BLEE'],mechanism:'Aminopenicilina más inhibidor de beta-lactamasas.'},
'nitrofurantoina':{adverse:['Neuropatía o toxicidad pulmonar en situaciones seleccionadas','No se usa para pielonefritis'],pk:'Concentración urinaria alta; exposición tisular sistémica insuficiente para infección renal.',classic:['Cistitis localizada no complicada'],missing:['Pielonefritis','Bacteriemia','Prostatitis'],mechanism:'Metabolitos reactivos bacterianos que dañan múltiples sistemas macromoleculares.'},
'doxiciclina':{adverse:['Fotosensibilidad','Esofagitis si no se ingiere con suficiente agua','Precauciones especiales en embarazo/infancia'],pk:'Tetraciclina, amplio alcance tisular e intracelular; inhibe 30S.',classic:['Patógenos atípicos respiratorios','Rickettsiosis','Infecciones por Chlamydia','Algunos MRSA comunitarios susceptibles'],missing:['No asumir que cubre toda enterobacteria o enfermedad invasiva'],mechanism:'Inhibe unión de aminoacil-tRNA a subunidad ribosomal 30S.'},
'azitromicina':{adverse:['Prolongación QT','Interacciones y efectos gastrointestinales'],pk:'Macrólido, exposición tisular elevada y actividad frente a algunas bacterias intracelulares.',classic:['Cobertura de atípicos en CAP','Tos ferina y patógenos respiratorios seleccionados','ITS específicas según protocolos'],missing:['No confiable para enterobacterales invasivas','No sustituye solo a betalactámico en CAP de alto riesgo'],mechanism:'Se une a 50S y limita síntesis de proteínas.'},
'metronidazol':{adverse:['Náusea, sabor metálico','Neuropatía con uso prolongado'],pk:'Buena biodisponibilidad oral; entra a anaerobios y protozoos susceptibles.',classic:['Abscesos intraabdominales en combinaciones','Infecciones anaerobias específicas','Vaginosis y protozoarios según diagnóstico'],missing:['No cubre aerobios grampositivos o gramnegativos','Cefepima + metronidazol cubre territorios distintos'],mechanism:'Activación reductiva en condiciones anaerobias produce radicales que lesionan ADN.'},
'linezolid':{adverse:['Trombocitopenia por curso prolongado','Interacciones serotoninérgicas','Neuropatía en tratamientos prolongados'],pk:'Excelente biodisponibilidad oral, actividad contra grampositivos resistentes.',classic:['Neumonía por MRSA','Infecciones seleccionadas por VRE','Infecciones de piel por grampositivos resistentes'],missing:['No cubre gramnegativos'],mechanism:'Oxazolidinona que inhibe formación del complejo de iniciación ribosomal 50S.'},
'ertapenem':{adverse:['Reacciones neurológicas raras, con riesgo asociado a ajuste renal','Alteración de microbiota'],pk:'Carbapenémico de dosificación frecuente cada 24 h según indicación; ajustar riñón.',classic:['Infecciones por Enterobacterales BLEE sin necesidad antipseudomónica','Infección intraabdominal polimicrobiana susceptible'],missing:['No es antipseudomónico','No cubre Acinetobacter'],mechanism:'Inhibe PBPs y pared bacteriana, betalactámico de amplio espectro.'},
'ceftarolina':{adverse:['Neutropenia con uso prolongado','Hipersensibilidad'],pk:'Cefalosporina con afinidad por PBP2a.',classic:['Neumonía bacteriana comunitaria según indicaciones','Infecciones cutáneas por MRSA'],missing:['No es antipseudomónica'],mechanism:'Cefalosporina con unión a PBP2a de MRSA, inhibe pared.'},
'piptazo':{adverse:['Diarrea / intolerancia','Ajuste renal'],pk:'Betalactámico tiempo-dependiente, con posible beneficio de infusión prolongada según protocolo.',classic:['Infección intraabdominal polimicrobiana','Neumonía nosocomial por organismos susceptibles','Infecciones graves con riesgo Pseudomonas'],missing:['No cubre MRSA','No es opción preferida para ESBL invasiva según IDSA'],mechanism:'Penicilina antipseudomónica con inhibidor de algunas beta-lactamasas.'}
};
function drugPageSections(a){const e=DRUG_EDU[a.id]||{}, rels=[...relsA(a.id)];const diseaseCases=allDiseases().filter(c=>[...c.first,...c.alternatives].some(rx=>norm(rx.drug).includes(norm(a.name)) || norm(a.name).includes(norm(rx.drug))));const dosing=fromManualForDrug(a);const recorded=rels.filter(r=>rstatus(r)==='active');const anchor=[['drug-mechanism','Mecanismo','01'],['drug-spectrum','Cobertura','02'],['drug-indications','Indicaciones','03'],['drug-dosing','Dosis y esquemas','04'],['drug-safety','PK/PD y seguridad','05'],['drug-questions','Autoevaluación','06'],['drug-source','Fuentes','07']];return `<div class="a18-profilehero a18-drughero" style="--hero:#8052B7"><div>${eyebrow('PHARMACOLOGY / '+a.family)}<h1>${H(a.name)}</h1><p class="a18-lead">${H(e.mechanism||a.mechanism||'Mecanismo farmacológico por documentar.')}</p><div class="a18-tagrow">${tags([a.family,a.subgroup,a.newer?'Agente reciente':'Clásico',a.context])}</div></div><div class="a18-heroside"><div class="a18-spectrumglyph">${ic('drugs',40)}</div>${metric('Familia',a.family)}${metric('Subfamilia',a.subgroup||'Sin subgrupo')}${metric('Cruces registrados',String(rels.length),'No equivale a cobertura total')}</div></div>${navAnchors(anchor)}
${sectionBlock('drug-mechanism','01','Farmacodinamia','Mecanismo de acción',`<div class="a18-duocol"><div class="a18-reading"><h3>¿Dónde actúa?</h3><p>${H(e.mechanism||a.mechanism||'Mecanismo no desarrollado para este agente.')}</p><p>${H(a.context||'Su utilidad clínica está determinada por especie, fenotipo y foco.')}</p></div><div class="a18-mechpanel"><span>DIANA FARMACOLÓGICA</span><strong>${H(a.subgroup||a.family)}</strong><p>Familia: ${H(a.family)}. Compartir familia no significa idéntico espectro; generaciones y modificaciones químicas pueden cambiar la actividad.</p></div></div>`)}
${sectionBlock('drug-spectrum','02','Microbiología aplicada','Cobertura y límites del espectro',`<div class="a18-spectrumbox">${D.groups.map(g=>{const rel=members(g.id).map(p=>relation(a.id,p.id));const known=rel.filter(Boolean);const active=known.filter(r=>rstatus(r)==='active').length;return `<button class="a18-territory" style="--tone:${grpcolor(g.id)}" data-act="drug-territory:${a.id}:${g.id}"><span class="a18-territoryname"><i></i><b>${H(g.name)}</b></span><strong>${known.length}<small> / ${members(g.id).length}</small></strong><span class="a18-tbar"><i style="width:${known.length/(members(g.id).length||1)*100}%"></i></span><small>${active} con actividad registrada</small></button>`}).join('')}</div><div class="a18-legendbrief">${statusBadge('active')}${statusBadge('conditional')}${statusBadge('none')}${statusBadge('unknown')}</div>${warning('El porcentaje visual representa proporción de pares documentados, nunca sensibilidad ni eficacia. Una región sin registros no significa ausencia de actividad.')}`)}
${sectionBlock('drug-indications','03','Enfermedades clásicas','Dónde se utiliza y por qué',`<div class="a18-duocol"><div class="a18-infobox"><h3>Aplicaciones conocidas</h3>${items(e.classic||[a.context].filter(Boolean))}</div><div class="a18-infobox"><h3>Situaciones donde NO asumir utilidad</h3>${items(e.missing||[a.limitations].filter(Boolean))}</div></div>${diseaseCases.length?`<div class="a18-diseasecards">${diseaseCases.map(c=>`<button ${sysStyle(c.system)} data-act="cond-pick:${c.id}"><span>${H(c.system)}</span><b>${H(c.title)}</b><small>${H(c.first.some(x=>norm(x.drug)===norm(a.name))?'Incluye primera elección OMS':'Alternativa contextual OMS')}</small></button>`).join('')}</div>`:''}`,'Estas indicaciones son contextuales: la misma especie puede requerir fármacos distintos según foco y gravedad.')}
${sectionBlock('drug-dosing','04','WHO AWaRe / pautas','Dosis, vía y escenarios específicos',`${dosing.length?`<div class="a18-dosegrid">${dosing.map(rx=>`<div class="a18-dose"><small>${H(rx.choice)} · ${H(rx.condition.title)}</small><b>${H(rx.dose)}</b><p>${H(rx.note||'')}</p><span>${H(rx.basis)}</span><button data-act="cond-pick:${rx.condition.id}">Abrir enfermedad ↗</button></div>`).join('')}</div>`:`<div class="a18-quietnote"><b>Sin pauta individual publicada en esta ficha.</b><p>El catálogo conserva ${H(a.name)}, pero una dosis segura depende de enfermedad, formulación, edad, función renal/hepática y situación clínica. No se mostrará una dosis genérica inventada.</p>${whoRefs()}</div>`}${warning('Dosis educativas tomadas de WHO AWaRe 2022 sólo en los escenarios indicados y para función renal/hepática normal; confirmar pauta local y vigencia antes de prescribir.')}`)}
${sectionBlock('drug-safety','05','Farmacocinética y vigilancia','PK/PD, toxicidad y precauciones',`<div class="a18-duocol"><div class="a18-infobox"><h3>Farmacocinética / PK-PD</h3><p>${H(e.pk||'La exposición en foco, biodisponibilidad, eliminación y objetivo PK/PD requieren datos específicos del agente y de la infección.')}</p></div><div class="a18-infobox"><h3>Reacciones adversas importantes</h3>${items(e.adverse||[])}</div></div>`)}
${sectionBlock('drug-questions','06','Práctica original','Preguntas de comprensión farmacológica',`<div class="a18-teaching"><div><h3>Comparación</h3><p>¿Qué cambia al sustituir ${H(a.name)} por otro integrante de ${H(a.family)}?</p><small>Explora diana, organismos cubiertos, vías, exposición y sitio infectado.</small></div><div><h3>Razonamiento</h3><p>¿En qué contexto elegirías un agente más estrecho que ${H(a.name)}?</p><small>La desescalada requiere evolución, cultivos y foco. Preguntas originales; no se reproduce LIR Q&A.</small></div></div>`)}
${sectionBlock('drug-source','07','Trazabilidad','Fuentes y grado de revisión',`<div class="a18-reflist">${linkRefs(a.referenceKeys)}${whoRefs()}<a class="a18-source" href="https://www.idsociety.org/practice-guideline/amr-guidance/" rel="noreferrer" target="_blank">IDSA · organismos resistentes ↗</a></div><p class="a18-smallmuted">Mecanismos desarrollados con orientación farmacológica de Lippincott 7ª, Ross & Wilson y Pharmacotherapy Principles & Practice; sin extracción indiscriminada ni copia de las preguntas protegidas.</p>`)}`}
function libraryConditions(){return allDiseases().filter(c=>state.clinicalSystem==='all'||!state.clinicalSystem||c.system===state.clinicalSystem).filter(c=>!state.clinicalSearch||`${c.title} ${c.system} ${c.overview}`.toLowerCase().includes(state.clinicalSearch.toLowerCase()));}
function clinicalSidebar(isLab=false){const syss=[...new Set(allDiseases().map(c=>c.system))],current=isLab?(state.labSystem||'all'):(state.clinicalSystem||'all');const selected=isLab?state.labClinical:state.clinicalId;const arr=allDiseases().filter(c=>current==='all'||c.system===current).filter(c=>!state.clinicalSearch||c.title.toLowerCase().includes(state.clinicalSearch.toLowerCase()));return `<aside class="a18-browser a18-systembrowser"><div class="a18-browserhead">${eyebrow(`WHO AWaRe / ${allDiseases().length} CONDICIONES`)}<h2>Enfermedades por sistema</h2><div class="a18-search">${ic('search',16)}<input id="clinical-search" value="${H(state.clinicalSearch||'')}" placeholder="Buscar enfermedad…"></div><div class="a18-systemchips"><button class="${current==='all'?'sel':''}" data-act="${isLab?'lab-system':'clinical-system'}:all">Todas</button>${syss.map(s=>`<button class="${current===s?'sel':''}" style="--sys:${sysColor(s)}" data-act="${isLab?'lab-system':'clinical-system'}:${H(s)}">${H(s)}</button>`).join('')}</div></div><div class="a18-conditionlist">${arr.map(c=>`<button data-act="${isLab?'lab-condition':'cond-pick'}:${c.id}" class="${selected===c.id?'selected':''}" ${sysStyle(c.system)}><span class="a18-systemicon">${ic('clinic',16)}</span><span><b>${H(c.title)}</b><small>${H(c.system)} · Capítulo ${c.chapter}</small></span>${c.first.length?`<em title="Cuenta con dosis trazada en la ficha">Rx</em>`:''}</button>`).join('')||'<p class="a18-empty">Sin coincidencias.</p>'}</div></aside>`}
function clinicalFull(c){const sourceLabel=c.level==='dosificacion_fuente'?'Incluye pautas de WHO':c.level==='sintesis_revisar'?'Síntesis educativa preliminar':'Índice del manual WHO';const axes=[['disease-what','Enfermedad','01'],['disease-path','Microbiología','02'],['disease-risk','Factores de riesgo','03'],['disease-choice','Primera elección','04'],['disease-alts','Alternativas','05'],['disease-safety','Alertas y bibliografía','06']];return `<div class="a18-profilehero a18-clinicalhero" ${sysStyle(c.system)}><div>${eyebrow(`${c.system} / ENFERMEDAD ${('0'+c.chapter).slice(-2)}`)}<h1>${H(c.title)}</h1><p class="a18-lead">${H(c.overview)}</p><div class="a18-tagrow">${tags([c.setting==='hospital'?'Hospital':'Atención primaria',sourceLabel,'WHO AWaRe 2022'])}</div></div><div class="a18-heroside">${ic('clinic',39)}${metric('Área',c.system)}${metric('Manual de referencia',`Cap. ${c.chapter}`,'Página '+c.page)}<b>${H(sourceLabel)}</b></div></div>${navAnchors(axes)}
${sectionBlock('disease-what','01','Definición y reconocimiento','¿Qué enfermedad es?',`<div class="a18-reading"><p>${H(c.overview)}</p><div class="a18-keypanel"><b>La pregunta terapéutica central</b><p>${H(c.why)}</p></div></div>`)}
${sectionBlock('disease-path','02','Etiología','Agentes que debes considerar',`${c.pathogens.length?`<div class="a18-chipdeck">${c.pathogens.map(n=>`<span>${ic('micro',15)} ${H(n)}</span>`).join('')}</div>`:`<div class="a18-quietnote">La relación microorganismo–enfermedad está pendiente de extracción individual del capítulo WHO. No asignamos agentes de otros síndromes.</div>`}`)}
${sectionBlock('disease-risk','03','Epidemiología y fisiopatología','Factores de riesgo y pistas clínicas',`${c.risks.length?items(c.risks):'<p class="a18-quietnote">Factores específicos pendientes de revisión de este capítulo.</p>'}`)}
${sectionBlock('disease-choice','04','Pauta terapéutica · adultos','Primera elección por enfermedad',`<div class="a18-dosegrid">${c.first.map(rx=>doseCard(rx,'Primera elección')).join('')||`<div class="a18-quietnote"><b>No se ha validado aún una pauta individual para este capítulo.</b><p>La enfermedad está catalogada y vinculada a su capítulo OMS, pero no inventaremos un «primer antibiótico» sin extraer la recomendación completa.</p></div>`}</div>`)}
${sectionBlock('disease-alts','05','Alternativas y decisiones','Otras opciones y cuándo considerar cambios',`<div class="a18-dosegrid">${c.alternatives.map(rx=>doseCard(rx,'Alternativa')).join('')||'<div class="a18-quietnote">Las alternativas individuales quedan pendientes de transcripción y revisión; no significa que no existan.</div>'}</div>`)}
${sectionBlock('disease-safety','06','Seguridad','Datos que cambian la conducta',`${items(c.redflags)}${warning('Las dosis mostradas proceden de WHO 2022, para adultos con función renal y hepática normal. Deben verificarse edad, peso, embarazo, alergias, función renal, interacciones y guía local vigente.') }<div class="a18-reflist">${whoRefs()}<a class="a18-source" href="https://www.idsociety.org/practice-guideline/complicated-urinary-tract-infections/" target="_blank" rel="noreferrer">IDSA · ITU complicada (cuando aplique) ↗</a></div>`)}
`}
function doseCard(rx,label){return `<div class="a18-dose"><small>${H(label)}</small><h3>${H(rx.drug)}</h3><b>${H(rx.dose)}</b><p>${H(rx.note||'')}</p><span>${H(rx.basis)}</span>${findRx(rx.drug)?`<button data-act="open-drug:${findRx(rx.drug).id}">Ver fármaco ↗</button>`:''}</div>`}
function clinicalPage(){const c=whoc(state.clinicalId)||allDiseases()[0];return `${pageHead('04','PATOLOGÍA INFECCIOSA','Enfermedades, <em>no solo rutas.</em>','Biblioteca de las enfermedades del manual WHO AWaRe, organizada por órgano y sistema. Define, contextualiza, identifica microorganismos y consulta tratamiento donde está validado.') }<div class="a18-library">${clinicalSidebar()}<article class="a18-article">${c?clinicalFull(c):'<div class="a18-empty">Cargando biblioteca de condiciones clínicas...</div>'}</article></div>`}
// Orientación didáctica de espectro, separada estrictamente del registro individual. NO es un antibiograma ni ranking terapéutico.
const CONCEPTUAL_MICRO={
'p-aeruginosa':['cefepima','ceftazidima','piptazo','meropenem','aztreonam','ciprofloxacino','ceftolozano-tazobactam','ceftazidima-avibactam','imipenem-cilastatina','cefiderocol'],
's-aureus-mssa':['cefazolina','oxacilina','dicloxacilina','flucloxacilina'],
's-aureus-mrsa':['vancomicina-iv','linezolid','daptomicina','ceftarolina'],
's-pneumoniae':['amoxicilina','ceftriaxona','penicilina-g'],
'e-coli-blee':['ertapenem','meropenem','trimetoprim-sulfametoxazol','ciprofloxacino'],
'b-fragilis':['metronidazol','piptazo','meropenem','ertapenem'],
'e-faecalis':['ampicilina','amoxicilina','vancomicina-iv','linezolid'],
'legionella':['azitromicina','levofloxacino'],
'mycoplasma':['doxiciclina','azitromicina','levofloxacino']
};
function conceptualMatch(drugId,pathogenId){return (CONCEPTUAL_MICRO[pathogenId]||[]).includes(drugId)}
function sortedForMicro(id){const rank={active:0,conditional:1,none:2,unknown:3};return [...D.antibiotics].sort((a,b)=>{const score=a=>{const s=relValue(a.id,id);const t=conceptualMatch(a.id,id);return s==='active'?0:(s==='conditional'&&t)?1:t?2:s==='conditional'?3:s==='none'?4:5};return score(a)-score(b)||a.name.localeCompare(b.name,'es')});}
function comparePage(){const p=P(state.compareMicro)||D.pathogens[0];const list=sortedForMicro(p.id).filter(a=>!state.comparSearch||`${a.name} ${a.family}`.toLowerCase().includes(state.comparSearch.toLowerCase()));const selected=state.compare.map(A).filter(Boolean);const groupOptions=D.groups.map(g=>({id:g.id,label:g.name,color:grpcolor(g.id),meta:members(g.id).length+' especies'}));const pOpts=D.pathogens.map(x=>({id:x.id,label:x.name,meta:G(x.groupId).name,color:grpcolor(x.groupId)}));return `${pageHead('05','HEAD-TO-HEAD / COMPARADOR','Comparar con <em>criterio clínico.</em>','Antes de añadir un medicamento, puedes ver cuáles tienen actividad registrada, cuáles dependen del contexto y cuáles no se evaluaron. No son recomendaciones automáticas.') }<div class="a18-comparetop"><div>${eyebrow('ELIGE TU MICROORGANISMO')}${renderPicker('compare-micro',p.id,pOpts,{placeholder:'Microorganismo objetivo'})}</div><div class="a18-comparestats">${['active','conditional','none','unknown'].map(st=>`<span class="s-${st}"><b>${D.antibiotics.filter(a=>relValue(a.id,p.id)===st).length}</b> ${ST[st].short}</span>`).join('')}</div></div><div class="a18-comparelayout"><aside class="a18-candidates"><div class="a18-browserhead">${eyebrow('CANDIDATOS VISIBLES')}<h2>Selecciona hasta 4 ATB</h2><div class="a18-search">${ic('search',16)}<input id="compare-search" placeholder="Buscar por nombre o familia" value="${H(state.comparSearch)}"></div><small>Primeros: actividad individual registrada o <b>perfil teórico de interés</b>. No es recomendación de primera elección.</small></div><div class="a18-candidatelist">${list.map(a=>{const st=relValue(a.id,p.id);return `<button class="a18-candidate ${state.compare.includes(a.id)?'is-selected':''}" data-act="compare-toggle:${a.id}"><span class="a18-candidateicon s-${st}">${ST[st].mark}</span><span><b>${H(a.name)}</b><small>${H(a.family)} · ${H(ST[st].name)}${conceptualMatch(a.id,p.id)?' · 🔎 Perfil teórico':''}</small></span><span class="a18-check">${state.compare.includes(a.id)?'✓':'+'}</span></button>`}).join('')}</div></aside><div class="a18-comparison"><div class="a18-compareheading">${eyebrow('MESA DE CONTRASTE')}<h2>${H(p.name)}</h2><p>Seleccionados: ${selected.length}/4 · cada cruce se interpreta por especie y situación clínica.</p></div><div class="a18-compgrid">${selected.map(a=>{const rel=relation(a.id,p.id),st=rstatus(rel),e=DRUG_EDU[a.id]||{};return `<article class="a18-comptile"><header><span>${H(a.family)}</span><button data-act="compare-toggle:${a.id}" title="Quitar">${ic('close',16)}</button></header><h3>${H(a.name)}</h3>${statusBadge(st)}<div class="a18-comprow"><small>¿Por qué entra en conversación?</small><p>${H(rel?.note||'No existe un cruce individual documentado. No podemos inferir resistencia ni actividad.')}</p></div><div class="a18-comprow"><small>Mecanismo</small><p>${H(e.mechanism||a.mechanism)}</p></div><div class="a18-comprow"><small>Uso / contexto</small><p>${H(e.classic?.slice(0,2).join(' · ')||a.context||'En revisión')}</p></div><div class="a18-comprow"><small>Limitaciones</small><p>${H(e.missing?.join(' · ')||a.limitations||'Por revisar')}</p></div><button class="a18-linkbtn" data-act="open-drug:${a.id}">Ficha completa ${ic('next',15)}</button></article>`}).join('')}${selected.length===0?'<div class="a18-quietnote">Selecciona candidatos en el panel izquierdo. Los símbolos te indican primero cuáles cuentan con registros.</div>':''}</div><div class="a18-evidencedistinction"><b>Dos capas separadas</b><span><strong>Estado individual</strong> = registro del corpus (actividad/variable/no útil/sin datos). <strong>Perfil teórico</strong> = familia o fármaco frecuentemente relevante para ese patógeno en bibliografía; puede fallar ante resistencia, dosis inadecuada o localización de infección.</span></div>${warning('No confundir actividad teórica de clase con primera elección. La susceptibilidad, el foco, PK/PD y guías vigentes determinan la interpretación clínica.')}</div></div>`}
